// Where a shot hit an animal and what it did. Plain JavaScript with no game imports
// (the build and tests use it too); dk.ulfen.hunting.hunt.HitZones is the Java twin.
//
// An animal's hit model (generated by src/lib/hitmodel.mjs) is in model pixels
// (16 per block at scale 1): y up, the animal faces -z, +x is its left. It has
//   cubes:  [m(12), min(3), max(3), zone]   every cube of the model in its rest pose
//   organs: [m(12), min(3), max(3), zone]   organ boxes inside the body
// where m is a 3x4 matrix taking model space into the cube's own (unrotated) space.

const STEP = 0.25; // sampling step along the bullet path, in model pixels

function apply(m, p) {
  return [
    m[0] * p[0] + m[1] * p[1] + m[2] * p[2] + m[3],
    m[4] * p[0] + m[5] * p[1] + m[6] * p[2] + m[7],
    m[8] * p[0] + m[9] * p[1] + m[10] * p[2] + m[11],
  ];
}

function rotate(m, d) {
  return [
    m[0] * d[0] + m[1] * d[1] + m[2] * d[2],
    m[4] * d[0] + m[5] * d[1] + m[6] * d[2],
    m[8] * d[0] + m[9] * d[1] + m[10] * d[2],
  ];
}

const inside = (q, min, max) => q[0] >= min[0] && q[0] <= max[0] && q[1] >= min[1] && q[1] <= max[1] && q[2] >= min[2] && q[2] <= max[2];

/** Ray/box slab test in the box's own space. Returns [tIn, tOut] or null. */
function slab(o, d, min, max) {
  let t0 = -Infinity, t1 = Infinity;
  for (let i = 0; i < 3; i++) {
    if (Math.abs(d[i]) < 1e-9) {
      if (o[i] < min[i] || o[i] > max[i]) return null;
      continue;
    }
    let a = (min[i] - o[i]) / d[i], b = (max[i] - o[i]) / d[i];
    if (a > b) [a, b] = [b, a];
    if (a > t0) t0 = a;
    if (b < t1) t1 = b;
    if (t0 > t1) return null;
  }
  if (t1 < 0) return null;
  return [Math.max(0, t0), t1];
}

/** First and last time a ray (model space, unit direction) is inside the model's silhouette. */
export function intersect(model, o, d) {
  let tIn = Infinity, tOut = -Infinity;
  for (const [m, min, max] of model.cubes) {
    const hit = slab(apply(m, o), rotate(m, d), min, max);
    if (!hit) continue;
    if (hit[0] < tIn) tIn = hit[0];
    if (hit[1] > tOut) tOut = hit[1];
  }
  return tIn === Infinity ? null : [tIn, tOut];
}

/** The zone at a point: organs by priority first, then whatever cube the point is in. */
export function zoneAt(model, p, priority) {
  let best = null, rank = Infinity;
  for (const [m, min, max, zone] of model.organs) {
    const r = priority.indexOf(zone);
    if (r < rank && inside(apply(m, p), min, max)) {
      best = zone;
      rank = r;
    }
  }
  if (best) return best;
  for (const [m, min, max, zone] of model.cubes) {
    const r = priority.indexOf(zone);
    if (r < rank && inside(apply(m, p), min, max)) {
      best = zone;
      rank = r;
    }
  }
  return best;
}

/**
 * Follow a bullet through the model. `budget` is how much tissue it can get through
 * (centimetres of muscle), `cmPerPx` converts model pixels to centimetres.
 * Returns null on a miss, else { entry, exit (null if it stayed inside), path: [{ zone, px }] }.
 */
export function trace(model, o, d, { budget, cmPerPx, zones, priority }) {
  const span = intersect(model, o, d);
  if (!span) return null;
  const path = [];
  let entry = null, last = null, left = budget, stopped = false;
  for (let t = span[0]; t <= span[1] + STEP; t += STEP) {
    const p = [o[0] + d[0] * t, o[1] + d[1] * t, o[2] + d[2] * t];
    const zone = zoneAt(model, p, priority);
    if (!zone) continue; // between legs, under the belly...
    if (!entry) entry = p;
    last = p;
    const seg = path[path.length - 1];
    if (seg && seg.zone === zone) seg.px += STEP;
    else path.push({ zone, px: STEP });
    left -= STEP * cmPerPx * (zones[zone]?.density ?? 1);
    if (left <= 0) {
      stopped = true;
      break;
    }
  }
  if (!entry) return null; // went through the bounding boxes' gaps only
  return { entry, exit: stopped ? null : last, stoppedAt: stopped ? last : null, path };
}

/** Closest distance between a ray and a point (model pixels). */
function missDistance(o, d, c) {
  const v = [c[0] - o[0], c[1] - o[1], c[2] - o[2]];
  const t = Math.max(0, v[0] * d[0] + v[1] * d[1] + v[2] * d[2]);
  return Math.hypot(v[0] - d[0] * t, v[1] - d[1] * t, v[2] - d[2] * t);
}

/** Which side of the animal a point on its surface is on, seen from the animal. */
export function sideOf(model, p) {
  const [min, max] = model.bounds;
  const rel = [0, 1, 2].map((i) => (p[i] - (min[i] + max[i]) / 2) / Math.max(1, (max[i] - min[i]) / 2));
  const ax = Math.abs(rel[0]), ay = Math.abs(rel[1]), az = Math.abs(rel[2]);
  if (ax >= ay && ax >= az) return rel[0] > 0 ? 'left' : 'right';
  if (az >= ay) return rel[2] < 0 ? 'front' : 'rear';
  return rel[1] > 0 ? 'top' : 'bottom';
}

const FATE_RANK = { none: 0, wound: 1, mortal: 2, kill: 3 };

/**
 * The full shot evaluation.
 *   model, zones, priority  hit model and zone table
 *   o, d                    ray in model space (pixels, unit direction)
 *   energy                  joules at impact
 *   penetration             centimetres of muscle the projectile can get through
 *   cmPerPx                 6.25 * the animal's scale
 *   minEnergy               the species' ethical minimum (0 for arrows: they kill by bleeding)
 * Returns a report: { hit, zones: [{ zone, percent }], fate, bleedSeconds, accuracy, grade,
 *   entry, exit, entrySide, exitSide, underpowered, notes: [] }.
 */
export function evaluate({ model, zones, priority, o, d, energy, penetration, cmPerPx, minEnergy = 0, bigGame = false }) {
  const res = trace(model, o, d, { budget: penetration, cmPerPx, zones, priority });
  const dist = missDistance(o, d, model.vital);
  const accuracy = Math.max(0, Math.min(100, Math.round(100 * (1 - dist / (2.5 * model.vitalRadius)))));
  if (!res) return { hit: false, zones: [], fate: 'none', bleedSeconds: 0, accuracy, grade: 'miss', notes: [] };

  const underpowered = minEnergy > 0 && energy < minEnergy;
  const notes = [];
  // Damage per zone: how much of the organ the bullet went through, scaled by energy.
  const sizes = model.zoneSize ?? {};
  const totals = new Map();
  for (const seg of res.path) totals.set(seg.zone, (totals.get(seg.zone) ?? 0) + seg.px);
  const power = minEnergy > 0 ? Math.min(1.2, Math.max(0.35, energy / minEnergy)) : 1;
  const hitZones = [...totals.entries()].map(([zone, px]) => ({
    zone,
    percent: Math.max(5, Math.min(100, Math.round((100 * power * px) / Math.max(1, sizes[zone] ?? 4)))),
  }));

  let fate = 'none', bleed = Infinity;
  for (const { zone } of hitZones) {
    const z = zones[zone];
    let f = z.fate, b = z.bleedSeconds;
    if (underpowered && f === 'kill') { f = 'mortal'; b = 6; }
    if (f === 'mortal') b *= underpowered ? 2 : 1;
    if (FATE_RANK[f] > FATE_RANK[fate]) fate = f;
    if (f === 'mortal') bleed = Math.min(bleed, b);
  }
  // Both lungs: faster.
  const lungs = totals.get('lungs') ?? 0;
  if (lungs > (sizes.lungs ?? 8) * 0.8) bleed = Math.min(bleed, 6);
  if (fate !== 'mortal') bleed = fate === 'kill' ? 0 : 0;

  const has = (z) => totals.has(z);
  let grade;
  if (has('heart') || (has('lungs') && accuracy >= 75)) grade = 'perfect';
  else if (has('lungs') || has('brain') || has('spine')) grade = 'good';
  else if (has('liver')) grade = 'poor';
  else if (fate === 'none') grade = 'miss';
  else grade = 'unethical';
  if (underpowered && grade !== 'miss') {
    grade = { perfect: 'good', good: 'poor', poor: 'unethical', unethical: 'unethical' }[grade];
    notes.push('underpowered');
  }
  if (!bigGame && minEnergy > 0 && energy > minEnergy * 6) notes.push('meat_damage');
  if (!res.exit) notes.push('no_exit');

  return {
    hit: true,
    zones: hitZones,
    fate,
    bleedSeconds: fate === 'mortal' ? bleed : 0,
    accuracy,
    grade,
    entry: res.entry.map((v) => Math.round(v * 10) / 10),
    exit: res.exit?.map((v) => Math.round(v * 10) / 10) ?? null,
    entrySide: sideOf(model, res.entry),
    exitSide: res.exit ? sideOf(model, res.exit) : null,
    underpowered,
    notes,
  };
}

/**
 * World -> model space for an entity standing at `pos` with body yaw `yaw` (degrees,
 * Minecraft convention) and render scale `scale`. Returns functions for points and directions.
 */
export function toModel(pos, yaw, scale) {
  const r = (yaw * Math.PI) / 180;
  const f = [-Math.sin(r), Math.cos(r)]; // forward (x, z)
  const right = [-Math.cos(r), -Math.sin(r)]; // the animal's right (x, z)
  const k = 16 / scale;
  const dir = (v) => [-(v.x * right[0] + v.z * right[1]), v.y, -(v.x * f[0] + v.z * f[1])];
  return {
    point: (p) => dir({ x: (p.x - pos.x) * k, y: (p.y - pos.y) * k, z: (p.z - pos.z) * k }),
    dir: (v) => {
      const d = dir(v);
      const n = Math.hypot(d[0], d[1], d[2]) || 1;
      return [d[0] / n, d[1] / n, d[2] / n];
    },
  };
}
